CREATE TABLE events (
  ts  DateTime,
  sku LowCardinality(String),
  qty UInt32
) ENGINE = MergeTree() ORDER BY ts;
INSERT INTO events VALUES (now(), 'WIDGET-1', 50), (now(), 'GADGET-2', 12);
SELECT sku, sum(qty) AS total FROM events GROUP BY sku ORDER BY total DESC;
SELECT quantile(0.99)(qty) FROM events;

