CREATE TABLE orders (id INT, payload VARIANT);
INSERT INTO orders SELECT 1, PARSE_JSON('{"customer":{"id":7},"total":120.5}');
SELECT payload:customer:id::INT AS cust, payload:total::FLOAT AS total FROM orders;
SELECT f.value:item::STRING AS item
FROM orders, LATERAL FLATTEN(input => PARSE_JSON('[{"item":"book"}]')) f;
SELECT * FROM orders AT (OFFSET => -3600);  -- time travel

